    23→import { DispatchEngine } from '../../agent-runtime/dispatch.js';
    24→import type { TaskStateChange, TaskStatus, InvocationEvent } from '../../agent-runtime/dispatch.js';
    25→import { DEFAULT_KSPEC_CLI_PATH } from '../../agent-runtime/invocation.js';
    26→import { initContext, loadMetaContext } from '../../parser/index.js';
    27→import type { PubSubManager } from '../websocket/pubsub.js';
    28→
    29→const VALID_TASK_STATUSES = new Set<string>([
    30→  "pending", "in_progress", "pending_review", "needs_work", "blocked", "completed", "cancelled",
    31→]);
    32→
    33→// Singleton dispatch engine per project path
    34→const engines: Map<string, DispatchEngine> = new Map();
    35→
    36→export interface AgentDispatchRouteOptions {
    37→  defaultProjectPath?: string;
    38→  /** PubSubManager for broadcasting agent invocation events to WebSocket clients */
    39→  pubsub?: PubSubManager;
    40→}
    41→
    42→/**
    43→ * Create a new dispatch engine with optional WebSocket broadcast wiring.
    44→ * AC: @daemon-agent-dispatch ac-3, ac-4
    45→ */
    46→function createEngine(projectDir: string, pubsub?: PubSubManager): DispatchEngine {
    47→  return new DispatchEngine({
    48→    projectDir,
    49→    kspecCliPath: DEFAULT_KSPEC_CLI_PATH,
    50→    onInvocationEvent: pubsub
    51→      ? (event: InvocationEvent) => {
    52→          pubsub.broadcast('agents', 'agent_invocation', {
    53→            session_id: event.session_id,
    54→            agent_id: event.agent_id,
    55→            task_id: event.task_id ?? null,
    56→            status: event.status,
    57→            timestamp: event.timestamp,
    58→          }, projectDir);
    59→        }
    60→      : undefined,
    61→    // AC: @cli-agent-commands ac-13, @daemon-agent-dispatch ac-8
    62→    onTextChunk: pubsub
    63→      ? (sessionId: string, agentId: string, taskId: string | null, text: string) => {
    64→          pubsub.broadcast('agents', 'agent_text_chunk', {
    65→            session_id: sessionId,
    66→            agent_id: agentId,
    67→            task_id: taskId,
    68→            text,
    69→            timestamp: Date.now(),
    70→          }, projectDir);
    71→        }
    72→      : undefined,
    73→  });
    74→}
    75→
    76→const stateChangeBodySchema = t.Object({
    77→  task_id: t.String(),
    78→  task_ref: t.Optional(t.String()),
    79→  from_status: t.String(),
    80→  to_status: t.String(),
    81→  timestamp: t.Optional(t.Number()),
    82→});
    83→
    84→type StateChangeBody = {
    85→  task_id: string;
    86→  task_ref?: string;
    87→  from_status: string;
    88→  to_status: string;
    89→  timestamp?: number;
    90→};
    91→
    92→function processStateChangeEvent(
    93→  engine: DispatchEngine | undefined,
    94→  body: StateChangeBody,
    95→): { accepted: boolean; reason?: string } {
    96→  if (!engine || !engine.getStatus().running) {
    97→    return { accepted: false, reason: 'Dispatch engine not running' };
    98→  }
    99→
   100→  if (!VALID_TASK_STATUSES.has(body.from_status) || !VALID_TASK_STATUSES.has(body.to_status)) {
   101→    return { accepted: false, reason: `Invalid status: from_status="${body.from_status}" to_status="${body.to_status}". Valid values: ${[...VALID_TASK_STATUSES].join(", ")}` };
   102→  }
   103→
   104→  const change: TaskStateChange = {
   105→    taskId: body.task_id,
   106→    taskRef: body.task_ref ?? `@${body.task_id}`,
   107→    fromStatus: body.from_status as TaskStatus,
   108→    toStatus: body.to_status as TaskStatus,
   109→    timestamp: body.timestamp ?? Date.now(),
   110→  };
   111→
   112→  engine.handleStateChange(change).catch((err) => {
   113→    console.error('[dispatch] Error handling state change event:', err);
   114→  });
   115→
   116→  return { accepted: true };
   117→}
   118→
   119→export function createAgentDispatchRoutes(options: AgentDispatchRouteOptions = {}) {
   120→  const { pubsub } = options;
   121→
   122→  return new Elysia({ prefix: '/api/agent' })
   123→
   124→    // AC: @daemon-agent-dispatch ac-2, ac-7 - CLI posts state change event to daemon
   125→    // AC: @agent-dispatch-engine ac-4
   126→    .post('/events', ({ body, projectContext }) => {
   127→      return processStateChangeEvent(engines.get(projectContext.path), body);
   128→    }, { body: stateChangeBodySchema })
   129→
   130→    // Legacy alias — same as /events
   131→    .post('/event', ({ body, projectContext }) => {
   132→      return processStateChangeEvent(engines.get(projectContext.path), body);
   133→    }, { body: stateChangeBodySchema })
   134→
   135→    // AC: @daemon-agent-dispatch ac-6 - Unified dispatch start/stop via action field
   136→    .post('/dispatch', async ({ body, projectContext }) => {
   137→      const projectDir = projectContext.path;
   138→
   139→      if (body.action === 'start') {
   140→        let engine = engines.get(projectDir);
   141→        if (engine?.getStatus().running) {
   142→          return { dispatch_enabled: true, reason: 'Already running' };
   143→        }
   144→
   145→        engine = createEngine(projectDir, pubsub);
   146→        engines.set(projectDir, engine);
   147→        await engine.start();
   148→
   149→        return { dispatch_enabled: true };
   150→      } else {
   151→        const engine = engines.get(projectDir);
   152→        if (!engine) {
   153→          return { dispatch_enabled: false, reason: 'No engine running' };
   154→        }
   155→
   156→        await engine.stop();
   157→        engines.delete(projectDir);
   158→
   159→        return { dispatch_enabled: false };
   160→      }
   161→    }, {
   162→      body: t.Object({
   163→        action: t.Union([t.Literal('start'), t.Literal('stop')]),
   164→      }),
   165→    })
   166→
   167→    // Start dispatch engine (legacy route)
   168→    .post('/dispatch/start', async ({ projectContext }) => {
   169→      const projectDir = projectContext.path;
   170→
   171→      let engine = engines.get(projectDir);
   172→      if (engine?.getStatus().running) {
   173→        return { started: false, reason: 'Already running', status: engine.getStatus() };
   174→      }
   175→
   176→      // AC: @agent-dispatch-engine ac-10 - pass kspecCliPath so task notes work from daemon-started engine
   177→      engine = createEngine(projectDir, pubsub);
   178→      engines.set(projectDir, engine);
   179→
   180→      await engine.start();
   181→
   182→      return { started: true, status: engine.getStatus() };
   183→    })
   184→
   185→    // Stop dispatch engine (legacy route)
   186→    .post('/dispatch/stop', async ({ projectContext }) => {
   187→      const projectDir = projectContext.path;
   188→      const engine = engines.get(projectDir);
   189→
   190→      if (!engine) {
   191→        return { stopped: false, reason: 'No engine running' };
   192→      }
   193→
   194→      await engine.stop();
   195→      engines.delete(projectDir);
   196→
   197→      return { stopped: true };
   198→    })
   199→
   200→    // Get dispatch engine status (internal format)
   201→    .get('/dispatch/status', ({ projectContext }) => {
   202→      const engine = engines.get(projectContext.path);
   203→
   204→      if (!engine) {
   205→        return {
   206→          running: false,
   207→          activeInvocations: 0,
   208→          queuedInvocations: 0,
   209→          invocations: [],
   210→        };
   211→      }
   212→
   213→      return engine.getStatus();
   214→    })
   215→
   216→    // AC: @daemon-agent-dispatch ac-5 - Public status endpoint
   217→    .get('/status', async ({ projectContext }) => {
   218→      const projectDir = projectContext.path;
   219→      const engineStatus = engines.get(projectDir)?.getStatus();
   220→
   221→      let agentDefinitions: Array<{ id: string; name: string; adapter: string }> = [];
   222→      try {
   223→        const ctx = await initContext(projectDir);
   224→        const meta = await loadMetaContext(ctx);
   225→        agentDefinitions = meta.agents.map((a) => ({
   226→          id: a.id,
   227→          name: a.name,
   228→          adapter: a.adapter ?? 'claude-agent-acp',
   229→        }));
   230→      } catch {
   231→        // Agent definitions unavailable — return empty array
   232→      }
   233→
   234→      return {
   235→        dispatch_enabled: engineStatus?.running ?? false,
   236→        active_invocations: engineStatus?.invocations?.map((inv) => ({
   237→          session_id: inv.sessionId,
   238→          agent_id: inv.agentId,
   239→          task_ref: inv.taskRef ?? null,
   240→          elapsed_ms: inv.elapsedMs,
   241→        })) ?? [],
   242→        queue_depth: engineStatus?.queuedInvocations ?? 0,
   243→        agent_definitions: agentDefinitions,
   244→      };
   245→    });
   246→}
   247→
   248→/**
   249→ * Get the dispatch engine for a project path (for integration with file watcher).
   250→ */
   251→export function getDispatchEngine(projectDir: string): DispatchEngine | undefined {
   252→  return engines.get(projectDir);
   253→}
   254→
   255→/**
   256→ * Stop all active dispatch engines. Called on daemon shutdown.
   257→ * AC: @agent-dispatch-engine ac-11 - daemon shutdown stops active engines
   258→ */
   259→export async function stopAllEngines(): Promise<void> {
   260→  const stopPromises: Promise<void>[] = [];
   261→  for (const [projectDir, engine] of engines) {
   262→    console.log(`[dispatch] Stopping engine for ${projectDir}...`);
   263→    stopPromises.push(
   264→      engine.stop().catch((err) => {
   265→        console.error(`[dispatch] Error stopping engine for ${projectDir}:`, err);
   266→      })
   267→    );
   268→  }
   269→  await Promise.all(stopPromises);
   270→  engines.clear();
   271→  console.log('[dispatch] All engines stopped');
   272→}
   273→
