     9→
    10→	// AC: @web-dashboard ac-1, ac-2, ac-3
    11→	// Task counts by status
    12→	interface TaskCounts {
    13→		ready: number;
    14→		in_progress: number;
    15→		pending_review: number;
    16→		blocked: number;
    17→		completed: number;
    18→	}
    19→
    20→	let counts = $state<TaskCounts>({
    21→		ready: 0,
    22→		in_progress: 0,
    23→		pending_review: 0,
    24→		blocked: 0,
    25→		completed: 0
    26→	});
    27→
    28→	let loading = $state(true);
    29→
    30→	onMount(async () => {
    31→		await loadCounts();
    32→	});
    33→
    34→	// AC: @multi-directory-daemon ac-27 - Reload data when project changes
    35→	$effect(() => {
    36→		const version = getProjectVersion();
    37→		if (version > 0) {
    38→			// Only reload if version has been incremented (not on initial load)
    39→			loadCounts();
    40→		}
    41→	});
    42→
    43→	async function loadCounts() {
    44→		try {
    45→			// Fetch all tasks to compute counts
    46→			const response = await fetchTasks({ limit: 1000 });
    47→			const tasks = response.items;
    48→
    49→			// Compute counts
    50→			const newCounts: TaskCounts = {
    51→				ready: 0,
    52→				in_progress: 0,
    53→				pending_review: 0,
    54→				blocked: 0,
    55→				completed: 0
    56→			};
    57→
    58→			// Build a set of completed task refs for dependency checking
    59→			const completedRefs = new Set(
    60→				tasks
    61→					.filter((t) => t.status === 'completed')
    62→					.flatMap((t) => [t._ulid, ...(t.slugs || [])])
    63→			);
    64→
    65→			for (const task of tasks) {
    66→				if (task.status === 'completed') {
    67→					newCounts.completed++;
    68→				} else if (task.status === 'in_progress') {
    69→					newCounts.in_progress++;
    70→				} else if (task.status === 'pending_review') {
    71→					newCounts.pending_review++;
    72→				} else if (task.status === 'blocked') {
    73→					newCounts.blocked++;
    74→				} else if (task.status === 'pending') {
    75→					// Check if blocked by dependencies
    76→					const deps = task.depends_on || [];
    77→					const hasUnmetDeps = deps.some((dep) => {
    78→						// Remove @ prefix if present
    79→						const ref = dep.startsWith('@') ? dep.slice(1) : dep;
    80→						return !completedRefs.has(ref);
    81→					});
    82→					if (hasUnmetDeps) {
    83→						newCounts.blocked++;
    84→					} else {
    85→						newCounts.ready++;
    86→					}
    87→				}
    88→			}
    89→
    90→			counts = newCounts;
    91→		} catch (err) {
    92→			console.error('Failed to load task counts:', err);
    93→		} finally {
    94→			loading = false;
    95→		}
    96→	}
    97→
    98→	// AC: @web-dashboard ac-3
    99→	function navigateToTasks(status: string) {
   100→		goto(`${base}/tasks?status=${status}`);
   101→	}
