  1→<script lang="ts">
  2→import type { ToolCallStatus } from '@kynetic/shared/aggregated-message';
  3→import { Ban, Check, ChevronDown, ChevronRight, Loader2, X } from 'lucide-svelte';
  4→
  5→interface Props {
  6→  toolName: string;
  7→  toolCallId: string;
  8→  input?: unknown;
  9→  output?: unknown;
 10→  success?: boolean;
 11→  toolStatus?: ToolCallStatus;
 12→  timestamp: string;
 13→}
 14→
 15→const {
 16→  toolName,
 17→  toolCallId,
 18→  input,
 19→  output,
 20→  success,
 21→  toolStatus = 'pending',
 22→  timestamp,
 23→}: Props = $props();
 24→
 25→let isExpanded = $state(false);
 26→let showFullOutput = $state(false);
 27→
 28→// Threshold for truncating large outputs (characters)
 29→const OUTPUT_TRUNCATE_THRESHOLD = 1000;
 30→
 31→function toggleExpanded() {
 32→  isExpanded = !isExpanded;
 33→}
 34→
 35→function toggleShowFullOutput() {
 36→  showFullOutput = !showFullOutput;
 37→}
 38→
 39→// Format JSON for display
 40→function formatJson(data: unknown): string {
 41→  if (data === undefined || data === null) return '';
 42→  try {
 43→    if (typeof data === 'string') return data;
 44→    return JSON.stringify(data, null, 2);
 45→  } catch {
 46→    return String(data);
 47→  }
 48→}
 49→
 50→// Get a useful preview of tool input
 51→function getPreview(data: unknown): string {
 52→  if (data === undefined || data === null) return '';
 53→
 54→  // For strings, show truncated version
 55→  if (typeof data === 'string') {
 56→    if (data.length <= 60) return data;
 57→    return `${data.slice(0, 60)}...`;
 58→  }
 59→
 60→  // For objects, try to extract useful summary
 61→  if (typeof data === 'object') {
 62→    const obj = data as Record<string, unknown>;
 63→
 64→    // Common tool input patterns
 65→    if (typeof obj.command === 'string') {
 66→      return obj.command.length <= 60 ? obj.command : `${obj.command.slice(0, 60)}...`;
 67→    }
 68→    if (typeof obj.file_path === 'string') {
 69→      return obj.file_path;
 70→    }
 71→    if (typeof obj.pattern === 'string') {
 72→      return `pattern: ${obj.pattern}`;
 73→    }
 74→    if (typeof obj.query === 'string') {
 75→      return obj.query.length <= 60 ? obj.query : `${obj.query.slice(0, 60)}...`;
 76→    }
 77→
 78→    // Show key count for complex objects
 79→    const keys = Object.keys(obj);
 80→    if (keys.length <= 3) {
 81→      return keys.join(', ');
 82→    }
 83→    return `${keys.length} properties`;
 84→  }
 85→
 86→  return String(data);
 87→}
 88→
 89→const formattedInput = $derived(formatJson(input));
 90→const formattedOutput = $derived(formatJson(output));
 91→const isOutputLarge = $derived(formattedOutput.length > OUTPUT_TRUNCATE_THRESHOLD);
 92→const displayedOutput = $derived(
 93→  isOutputLarge && !showFullOutput
 94→    ? `${formattedOutput.slice(0, OUTPUT_TRUNCATE_THRESHOLD)}...`
 95→    : formattedOutput,
 96→);
 97→const preview = $derived(getPreview(input));
 98→const displayName = $derived(toolName || 'tool');
 99→
100→// Determine if this is a terminal state (has result)
101→const isTerminal = $derived(
102→  toolStatus === 'completed' || toolStatus === 'failed' || toolStatus === 'cancelled',
103→);
104→const isRunning = $derived(toolStatus === 'pending' || toolStatus === 'running');
105→
106→// Border and text colors based on status
107→const borderColor = $derived(
108→  toolStatus === 'failed'
109→    ? 'border-red-900/50'
110→    : toolStatus === 'cancelled'
111→      ? 'border-amber-900/50'
112→      : toolStatus === 'completed'
113→        ? 'border-emerald-900/50'
114→        : 'border-blue-900/50',
115→);
116→const textColor = $derived(
117→  toolStatus === 'failed'
118→    ? 'text-red-400 hover:text-red-300'
119→    : toolStatus === 'cancelled'
120→      ? 'text-amber-400 hover:text-amber-300'
121→      : toolStatus === 'completed'
122→        ? 'text-emerald-400 hover:text-emerald-300'
123→        : 'text-blue-400 hover:text-blue-300',
124→);
125→const badgeBg = $derived(
126→  toolStatus === 'failed'
127→    ? 'bg-red-950/50'
128→    : toolStatus === 'cancelled'
129→      ? 'bg-amber-950/50'
130→      : toolStatus === 'completed'
131→        ? 'bg-emerald-950/50'
132→        : 'bg-blue-950/50',
133→);
134→</script>
135→
136→<div class="tool-card ml-8 border-l-2 {borderColor} py-1 pl-3" class:running={isRunning}>
137→	<button
138→		onclick={toggleExpanded}
139→		class="flex w-full items-center gap-2 text-left text-xs transition-colors duration-200 {textColor}"
140→	>
141→		<!-- Timestamp on left -->
142→		<span class="font-mono text-zinc-500 text-[10px]">{timestamp}</span>
143→
144→		<!-- Expand/collapse icon -->
145→		{#if isExpanded}
146→			<ChevronDown class="h-3 w-3 text-zinc-600" />
147→		{:else}
148→			<ChevronRight class="h-3 w-3 text-zinc-600" />
149→		{/if}
150→
151→		<!-- Tool name badge -->
152→		<span class="rounded px-1.5 py-0.5 font-mono {badgeBg}">
153→			{displayName}
154→		</span>
155→
156→		<!-- Status indicator -->
157→		{#if isRunning}
158→			<Loader2 class="h-3 w-3 animate-spin text-blue-400" />
159→		{:else if toolStatus === 'completed'}
160→			<Check class="h-3 w-3 text-emerald-500" />
161→		{:else if toolStatus === 'failed'}
162→			<X class="h-3 w-3 text-red-500" />
163→		{:else if toolStatus === 'cancelled'}
164→			<Ban class="h-3 w-3 text-amber-500" />
165→		{/if}
166→
167→		<!-- Preview (when collapsed) -->
168→		{#if !isExpanded && preview}
169→			<span class="truncate text-zinc-600">{preview}</span>
170→		{/if}
171→	</button>
172→
173→	<!-- Expanded content -->
174→	{#if isExpanded}
175→		<div class="mt-2 space-y-2">
176→			<!-- Input section -->
177→			{#if formattedInput}
178→				<div>
179→					<div class="text-[10px] uppercase tracking-wide text-zinc-600 mb-1">Input</div>
180→					<pre class="max-h-48 overflow-auto rounded bg-zinc-950 p-2 text-xs text-zinc-400">{formattedInput}</pre>
181→				</div>
182→			{/if}
183→
184→			<!-- Output section (only when available) -->
185→			{#if formattedOutput}
186→				<div>
187→					<div class="text-[10px] uppercase tracking-wide text-zinc-600 mb-1">Output</div>
188→					<pre class="{showFullOutput ? 'max-h-none' : 'max-h-48'} overflow-auto rounded bg-zinc-950 p-2 text-xs {toolStatus === 'failed' ? 'text-red-400' : 'text-zinc-400'}">{displayedOutput}</pre>
189→					{#if isOutputLarge}
190→						<button
191→							type="button"
192→							onclick={toggleShowFullOutput}
193→							class="mt-1 text-xs text-zinc-500 hover:text-zinc-400 transition-colors"
194→						>
195→							{showFullOutput ? 'Show less' : `Show more (${Math.round(formattedOutput.length / 1000)}KB)`}
196→						</button>
197→					{/if}
198→				</div>
199→			{/if}
200→		</div>
201→	{/if}
202→</div>
203→
204→<style>
205→	.tool-card {
206→		transition: border-color 0.2s ease;
207→	}
208→
209→	/* Subtle pulse for running state */
210→	.tool-card.running {
211→		animation: tool-pulse 2s ease-in-out infinite;
212→	}
213→
214→	@keyframes tool-pulse {
215→		0%, 100% {
216→			opacity: 1;
217→		}
218→		50% {
219→			opacity: 0.85;
220→		}
221→	}
222→</style>
223→

