163→        continue;
164→      }
165→
166→      // Increment sequence number for this connection
167→      ws.data.seq++;
168→
169→      // AC: @api-contract ac-29, @trait-websocket-protocol ac-3
170→      const message: BroadcastEvent = {
171→        msg_id: ulid(),
172→        seq: ws.data.seq,
173→        timestamp: new Date().toISOString(),
174→        topic,
175→        event,
176→        data
177→      };
178→
179→      ws.send(JSON.stringify(message));
180→    }
181→  }
182→
183→  /**
